import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { transportSchema, type Transport } from "./transport.js";

/**
 * The result of a WebAuthn credential registration via `navigator.credentials.create()`, as
 * specified in
 * [AuthenticatorAttestationResponse](https://developer.mozilla.org/en-US/docs/Web/API/AuthenticatorAttestationResponse).
 */
export type Response = {
  /**
   * The authenticator data and an attestation statement for a new key pair generated by the
   * authenticator.
   */
  attestationObject?: string;
  /**
   * This property contains the JSON-compatible serialization of the data passed from the browser to
   * the authenticator in order to generate this credential.
   */
  clientDataJson?: string;
  /**
   * An array of strings providing hints as to the methods the client could use to communicate with
   * the relevant authenticator of the public key credential to retrieve.
   */
  transports?: Transport[];
};

export const responseSchema: Schema<Response> = s.object<Response>({
  attestationObject: s.optional(s.string()),
  clientDataJson: s.optional(s.string()),
  transports: s.optional(s.array(s.lazy(() => transportSchema))),
  _keysMap: {
    clientDataJson: "clientDataJSON",
  },
});
